/**
 * Every sound shipped with the game. Files live in public/assets/audio/ as .ogg + .mp3 (Howler picks the first
 * format the browser decodes) and are all generated by `node scripts/generate-audio.mjs` — see LICENSES.md there.
 */
export type CanonicalSfx =
  | 'cannon-fire'
  | 'cannon-whistle'
  | 'splash-miss'
  | 'impact-wood'
  | 'fire-loop'
  | 'hull-creak'
  | 'mast-snap'
  | 'sinking-groan'
  | 'bubbles'
  | 'crew-shout-hit'
  | 'crew-cheer'
  | 'bell-victory'
  | 'drum-defeat'
  | 'ui-click'
  | 'ui-hover'
  | 'place-ship'
  | 'rotate-ship'
  | 'sail-flap'
  | 'thunder'
  | 'gull'

/** Names used by the pre-pirate UI (`src/ui`). They keep working and map onto the new set. */
export type LegacySfx = 'fire' | 'hit' | 'miss' | 'sunk' | 'victory' | 'defeat' | 'place'
/** Anything `playSfx` accepts. */
export type Sfx = CanonicalSfx | LegacySfx
export type SfxName = Sfx

export const LEGACY_SFX: Record<LegacySfx, CanonicalSfx> = {
  fire: 'cannon-fire',
  hit: 'impact-wood',
  miss: 'splash-miss',
  sunk: 'sinking-groan',
  victory: 'bell-victory',
  defeat: 'drum-defeat',
  place: 'place-ship',
}

export function resolveSfx(name: Sfx): CanonicalSfx {
  return name in LEGACY_SFX ? LEGACY_SFX[name as LegacySfx] : (name as CanonicalSfx)
}

/** Variant files (basenames, no extension) per SFX; variants are cycled so repeats never sound identical. */
const CANONICAL_FILES: Record<CanonicalSfx, readonly string[]> = {
  'cannon-fire': ['cannon-fire-1', 'cannon-fire-2', 'cannon-fire-3'],
  'cannon-whistle': ['cannon-whistle'],
  'splash-miss': ['splash-miss-1', 'splash-miss-2', 'splash-miss-3'],
  'impact-wood': ['impact-wood-1', 'impact-wood-2', 'impact-wood-3'],
  'fire-loop': ['fire-loop'],
  'hull-creak': ['hull-creak-1', 'hull-creak-2'],
  'mast-snap': ['mast-snap'],
  'sinking-groan': ['sinking-groan'],
  bubbles: ['bubbles'],
  'crew-shout-hit': ['crew-shout-hit'],
  'crew-cheer': ['crew-cheer'],
  'bell-victory': ['bell-victory'],
  'drum-defeat': ['drum-defeat'],
  'ui-click': ['ui-click'],
  'ui-hover': ['ui-hover'],
  'place-ship': ['place-ship'],
  'rotate-ship': ['rotate-ship'],
  'sail-flap': ['sail-flap'],
  thunder: ['thunder'],
  gull: ['gull-1', 'gull-2'],
}

/** Canonical names plus the legacy aliases (pointing at the same files). */
export const SFX_FILES: Record<Sfx, readonly string[]> = {
  ...CANONICAL_FILES,
  ...(Object.fromEntries(Object.entries(LEGACY_SFX).map(([k, v]) => [k, CANONICAL_FILES[v]])) as Record<LegacySfx, readonly string[]>),
}

/** The real sound set (no aliases) — what the demo lists. */
export const SFX_NAMES = Object.keys(CANONICAL_FILES) as CanonicalSfx[]

/** SFX authored as seamless loops (`playSfx` of these returns a handle you must `stop()`). */
export const LOOPING_SFX: ReadonlySet<CanonicalSfx> = new Set<CanonicalSfx>(['fire-loop', 'bubbles'])

/** Big moments pull the music down for a while so they read clearly. */
export const SFX_DUCK_MS: Partial<Record<CanonicalSfx, number>> = {
  'sinking-groan': 2400,
  'mast-snap': 1200,
  'bell-victory': 3200,
  'drum-defeat': 3000,
  thunder: 1500,
}

/** Per-sound base gain (0..1) applied under the SFX bus so the set is balanced. */
export const SFX_GAIN: Partial<Record<CanonicalSfx, number>> = {
  'cannon-fire': 1,
  'cannon-whistle': 0.55,
  'splash-miss': 0.8,
  'impact-wood': 0.9,
  'fire-loop': 0.5,
  'hull-creak': 0.6,
  'ui-click': 0.5,
  'ui-hover': 0.3,
  'place-ship': 0.7,
  'rotate-ship': 0.6,
  'sail-flap': 0.6,
  gull: 0.45,
  bubbles: 0.6,
}

export type MusicTrack = 'menu' | 'battle'

export const MUSIC_FILES = {
  intro: 'music-intro',
  menu: 'music-menu',
  battle: 'music-battle',
} as const

export const AMBIENCE_FILES = {
  sea: 'ambience-sea',
  storm: 'ambience-storm',
} as const

/** @deprecated kept for callers of the pre-pirate API; `MUSIC_FILES` / `AMBIENCE_FILES` are the real thing. */
export const LOOP_FILES = {
  music: MUSIC_FILES.menu,
  ambience: AMBIENCE_FILES.sea,
} as const

/** Every basename that must exist as .ogg + .mp3 (checked by manifest.test.ts against the generator). */
export const ALL_AUDIO_FILES: readonly string[] = [
  ...new Set([...Object.values(CANONICAL_FILES).flat(), ...Object.values(MUSIC_FILES), ...Object.values(AMBIENCE_FILES)]),
]

export const AUDIO_FORMATS = ['ogg', 'mp3'] as const

/** Public URLs for a basename, honouring Vite's `base` (GitHub Pages serves from /battleship-devin/). */
export function audioUrls(basename: string): string[] {
  const base = import.meta.env.BASE_URL ?? '/'
  return AUDIO_FORMATS.map((ext) => `${base}assets/audio/${basename}.${ext}`)
}
